function svMultiChips(id,label,choices,featId){
  var wrap=el("div");
  if(label) wrap.appendChild(el("div","subh",label));
  var chips=el("div","chips"); chips.id=id;   /* the other 47 chip rows carry one */
  function list(){ var l=svGet(id,null); return Array.isArray(l)?l:[]; }
  function refresh(){
    var l=list();
    chips.querySelectorAll(".chip").forEach(function(c,i){ c.className="chip"+(l.indexOf(choices[i][0])>=0?" on":""); });
  }
  choices.forEach(function(ch){
    var c=el("button","chip",ch[1]);
    c.onclick=function(){
      var l=list().slice(), i=l.indexOf(ch[0]);
      if(i>=0) l.splice(i,1); else l.push(ch[0]);
      svSet(id,l);
      /* same seeding rule as svChips — a zone picked with its Amount at 0 was
         inert. Only on the way IN; emptying the list must not seed anything. */
      if(l.length&&stSeedAmount(featId,id)) stRefreshUI();
      stSync(featId); refresh();
    };
    chips.appendChild(c);
  });
  wrap.appendChild(chips);
  ST.refreshFns.push(refresh); refresh();
  return wrap;
}
