function stSnapshot(){ return JSON.parse(JSON.stringify({t1:state.st.t1,t2:state.st.t2,v:state.st.v,pend:state.st.pend})); }
function stApplyPreset(p){
  if(ST.busy) return;
  if(state.st.preset===p.key){
    /* tap again = restore the exact pre-preset snapshot (params + queue) */
    if(ST.presetSnap){
      state.st.t1=ST.presetSnap.t1; state.st.t2=ST.presetSnap.t2;
      state.st.v=ST.presetSnap.v; state.st.pend=ST.presetSnap.pend;
    }
    state.st.preset=null; ST.presetSnap=null;
  } else {
    /* Only snapshot when stepping in from the user's OWN state. Overwriting it
       while a preset is live made "tap again" return to preset A instead of to
       the hand-built look, which is the thing worth getting back to. */
    if(!state.st.preset||!ST.presetSnap) ST.presetSnap=stSnapshot();
    /* v5.25 — this used to only overlay p.t1/p.t2/p.sv's OWN keys onto
       whatever was already there, so a value a PREVIOUS preset set (or a
       Tier-3 AI-queue entry a previous preset's feats turned on) survived
       into a preset that never mentions it — reaching not just the canvas
       but the composed GENERATE prompt. Full-reset-then-overlay, matching
       stApplyRecipe's already-correct pattern below. */
    var pd1=stDefT1(); for(var k in pd1) state.st.t1[k]=(p.t1&&typeof p.t1[k]==="number")?p.t1[k]:pd1[k];
    var pd2=stDefT2(); for(var k2 in pd2) state.st.t2[k2]=(k2==="finish")?((p.t2&&(p.t2.finish===null||typeof p.t2.finish==="string"))?p.t2.finish:null):((p.t2&&+p.t2[k2])||0);
    state.st.v=p.sv?JSON.parse(JSON.stringify(p.sv)):{};
    state.st.preset=p.key;
    /* re-sync EVERY known feature (not just this preset's own p.feats) against
       the freshly-replaced state.st.v — stSync() is idempotent, adding a pend
       entry only when f.calc() reads live values and removing one when it
       doesn't, so this correctly clears any feature a PREVIOUS preset queued
       that the new preset doesn't re-declare. */
    Object.keys(ST.feats).forEach(stSync);
    try{
      if(!localStorage.getItem("hnk_st_preset_hint")){
        localStorage.setItem("hnk_st_preset_hint","1");
        toast(L9({my:"ထပ်တစ်ချက်နှိပ်ရင် မူလအတိုင်းပြန်ဖြစ်မယ်",en:"Tap the card again to restore the previous look"}));
      }
    }catch(e){}
    if(navigator.vibrate&&window.innerWidth<720){ try{ navigator.vibrate(8); }catch(e2){} }
  }
  stRecomputeGhosts(); stRefreshUI(); stRenderPend(); stRenderPresetCards();
  stT1Changed(); stT2Changed();
  saveState();
}
function stPresetT1Full(p){ var o=stDefT1(); if(p.t1) for(var k in p.t1) o[k]=p.t1[k]; return o; }

  /* ===== app 21374–21413: stT2Fragments + stUsesRefActive + stComposePrompt ===== */
function stT2Fragments(){
  var b=state.st.t2, L=[];
  if(b.smooth) L.push(stLine("smooth",b.smooth));
  if(b.denoise) L.push("Reduce fine noise and chroma speckle at "+b.denoise+"%.");
  if(b.even||b.deyellow) L.push("Even out patchy skin tone"+(b.even?" at "+b.even+"%":"")+(b.deyellow?" and remove yellow/sallow cast at "+b.deyellow+"%":"")+".");
  if(b.white) L.push(stLine("tone",b.white));
  if(b.rosy>0) L.push("Add a rosy healthy flush to the cheeks at "+b.rosy+"%.");
  else if(b.rosy<0) L.push("Reduce excess redness in the skin at "+(-b.rosy)+"%.");
  if(b.deshine) L.push("Remove oily shine from the forehead, nose and cheeks at "+b.deshine+"%.");
  if(b.gloss>0) L.push("Add a healthy glossy sheen to the skin at "+b.gloss+"%.");
  else if(b.gloss<0) L.push("Matte down glossy skin highlights at "+(-b.gloss)+"%.");
  if(b.teeth) L.push(stLine("teeth",b.teeth));
  if(b.eyeb) L.push(stLine("eyeWhite",b.eyeb)+" Brighten the eyes naturally at "+b.eyeb+"%.");
  if(b.radiance) L.push("Add luminous radiance to the skin at "+b.radiance+"%.");
  if(b.finish&&b.finishV) L.push("Give the skin a "+(b.finish==="cream"?"cream":b.finish)+" finish at "+b.finishV+"%, natural micro-texture preserved.");
  return L;
}
/* opt-in reference-transfer path: at least one queued feature declares usesRef AND a ref photo exists */
function stUsesRefActive(){
  if(!state.st.refX) return false;
  for(var i=0;i<state.st.pend.length;i++){
    var f=ST.feats[state.st.pend[i].id];
    if(f&&f.usesRef) return true;
  }
  return false;
}
function stComposePrompt(){
  var frags=stT2Fragments();
  state.st.pend.forEach(function(e){ var f=stFragOf(e); if(f) frags.push(f); });
  return "PORTRAIT RETOUCH TASK on IMAGE 1 ("+stTargetPhrase()+").\n"+
    "Apply ONLY the following edits at the stated strengths. Keep identity, pose,\n"+
    "clothing and background unchanged unless an edit explicitly says otherwise:\n"+
    "FRAMING LOCK: return the photo at IMAGE 1's exact aspect ratio, crop, camera\n"+
    "angle and subject scale. Never zoom, pan, re-centre, extend the canvas or\n"+
    "change the shape of the frame — this is a retouch, not a recompose.\n"+
    frags.map(function(f){ return "- "+f; }).join("\n")+
    (stUsesRefActive()?"\nIMAGE 2 = style/makeup/color reference ONLY — never return it.":"")+
    "\nPhoto-realistic professional result. Do not beautify beyond the listed edits.";
}

