/* Retouch Pro's 50 slider chips now render in ONE place — the Retouch page's
   Sliders tab (#rsChips). The Studio copy (#rtChips) left with v4.23.0's
   Retouch A/Retouch B rebuild; the host list stays an array so a future second host
   is one entry away, and renderRtChipsInto is null-safe regardless. */
var RT_CHIP_HOST_IDS = ["rsChips"];
function renderRtChipsInto(hostId){
  var host=$(hostId); if(!host) return;
  host.innerHTML="";
  var byKeyRt={}; D.retouch.sliders.forEach(function(s){ byKeyRt[s.key]=s; });
  var totalOn=0;
  RT_GROUPS.forEach(function(grp){
    var groupOn=grp.keys.filter(function(key){ return byKeyRt[key] && state.rt[byKeyRt[key].key]; }).length;
    totalOn+=groupOn;
    host.appendChild(el("div","subh",grp.t+(groupOn?" · "+groupOn:"")));
    var row=el("div","chips");
    grp.keys.forEach(function(key){
      var s=byKeyRt[key]; if(!s) return;
      var on = !!state.rt[s.key];
      var lbl = rtLabel(s) + (s.bipolar && state.rt[s.key]===-1 ? " (−)" : "");
      var c=el("button","chip"+(on?" on":""), lbl);
      c.title = rtLine(s).replace(/^- /,"");
      c.onclick=function(){
        /* off -> + ; + -> (bipolar? − : off) ; − -> off */
        if(!state.rt[s.key]) state.rt[s.key]=1;
        else if(state.rt[s.key]===1 && s.bipolar && s.lineNeg) state.rt[s.key]=-1;
        else state.rt[s.key]=0;
        renderRtChips(); renderAddonSummary(); renderRsSelCount(); renderRsBundleGrid();
      };
      row.appendChild(c);
    });
    host.appendChild(row);
  });
}
function renderRtChips(){ RT_CHIP_HOST_IDS.forEach(renderRtChipsInto); }
renderRtChips();

