function rsSetMode(mode){
  rsMode=mode;
  [["onetap","rsTabOnetap","rsOnetapPane"],["sliders","rsTabSliders","rsSlidersPane"]].forEach(function(m){
    var tabBtn=$(m[1]); if(tabBtn) tabBtn.className="chip"+(m[0]===mode?" on":"");
    var pane=$(m[2]); if(pane) pane.style.display=(m[0]===mode?"":"none");
  });
  $("btnRsGen").style.display = mode==="onetap" ? "none" : "";
  if(RS_GEN_LABELS[mode]) setIcnText($("btnRsGen"),RS_GEN_LABELS[mode].icon,RS_GEN_LABELS[mode].label);
  rsSyncGenCardVisibility();
}
/* In One-Tap mode the Generate button is hidden (chips fire generation
   directly) — but the card wrapping it also holds the spinner, status line
   and Retry button, and hiding only the button left an empty rounded box
   with nothing in it sitting between the presets and the result on every
   first visit. Show the card only when it actually has something to say:
   Sliders mode (Generate lives there), an active generation, or a Retry
   waiting for the user. */
function rsSyncGenCardVisibility(){
  var card=$("rsGenCard"); if(!card) return;
  var show = rsMode!=="onetap" || rsBusy || $("btnRsRetry").style.display!=="none";
  card.style.display = show ? "" : "none";
}
$("rsTabOnetap").onclick=function(){ rsSetMode("onetap"); };
$("rsTabSliders").onclick=function(){ rsSetMode("sliders"); };

/* Strength (30/60/90) drives BOTH modes now — one-tap presets embed it in
   their instruction text, sliders embed it via rtLine()'s %-substitution —
   so both panes render their own copy of the same chips from one shared
   state.rtStrength, kept in sync the same dual-host way Retouch Pro's
   slider chips already are (#rtChips/#rsChips via RT_CHIP_HOST_IDS). */
var RS_STRENGTH_HOST_IDS = ["rsStrengthChips","rsOnetapStrengthChips"];
function renderRsStrengthChips(){
  RS_STRENGTH_HOST_IDS.forEach(function(hostId){
    var host=$(hostId); if(!host) return;
    host.innerHTML="";
    [60,90,100].forEach(function(v){
      var b=el("button","chip"+(v===state.rtStrength?" on":""), v+"%");
      b.onclick=function(){
        state.rtStrength=v;
        renderRsStrengthChips();
        renderRtChips(); renderAddonSummary(); renderRsPresetGrid();
      };
      host.appendChild(b);
    });
  });
}
