/* generate: steer the shared $("btnGen") provider/fallback dispatcher's
   inputs (prompt text + IMAGE 1) instead of duplicating that ~150-line
   dispatcher. state.hist growing tells us it actually produced a result. */
var rsBusy=false;
/* v4.28: cooperative Stop flag for V2/Retouch runs (checked after the shared
   dispatcher await + between batch photos) — armed by btnV2Stop/btnRsStop,
   cleared at every user-initiated run start */
var rsStop=false;
/* v4.28: one-shot arm for the multi-photo Batch pick on the shared #filePick */
var rsBatchArmed=false;

  /* ===== app 12587–12719: V2 defaults + state.v2 + house presets ===== */
var V2_DEF={ strength:60, mode:"both", quality:"fast", balance:0, blemish:60,
             deshine:0, tone:"off", toneStrength:42, hair:"off", outfit:"off",
             teeth:"off", eyes:"off", eyebags:"off", body:"soft", shape:"off" };
/* v5.6 — body:"soft" is the DEFAULT: the studios retouch body skin on every
   order, and a face-only default left neck/arms visibly rougher than the
   face ("one skin" rule). Explicit off still available. */
state.v2=JSON.parse(JSON.stringify(V2_DEF));
if(state.v2Saved){ /* tolerant restore — same pattern as state.stSaved */
  try{ state.v2=Object.assign(JSON.parse(JSON.stringify(V2_DEF)), state.v2Saved); }catch(e){}
  delete state.v2Saved;
}
state.v2Armed=false; state.v2BatchN=0; /* session-only (next-photo auto-start + batch counter) */
/* v4.45 — named house presets over the whole 10-parameter hero
   ("Bride 60", "Groom 80", "Grandma 30"): one tap restores every setting. */
state.v2Presets=[];
if(state.v2PresetsSaved){
  try{
    state.v2Presets=state.v2PresetsSaved.filter(function(p){
      return p && typeof p.name==="string" && p.v && typeof p.v==="object";
    }).slice(0,8).map(function(p){
      return { name:String(p.name).slice(0,24), v:Object.assign(JSON.parse(JSON.stringify(V2_DEF)), p.v) };
    });
  }catch(e){}
  delete state.v2PresetsSaved;
}
function v2SavePreset(){
  var nm=H.promptText(L9({my:"Preset နာမည် (ဥပမာ — Bride 60)",en:"Preset name (e.g. Bride 60)"}),"");
  if(nm===null) return;
  nm=String(nm).slice(0,24).trim(); if(!nm) return;
  state.v2Presets=state.v2Presets.filter(function(p){ return p.name!==nm; });
  state.v2Presets.unshift({ name:nm, v:JSON.parse(JSON.stringify(state.v2)) });
  if(state.v2Presets.length>8){
    state.v2Presets.length=8;
    toast(L9({my:"Preset ၈ ခုပြည့်လို့ အဟောင်းဆုံးကို ဖယ်လိုက်ပါပြီ",en:"Preset list full — removed the oldest"}),"ok");
  }
  saveState(); renderV2Hero();
  toast(L9({my:"'"+nm+"' preset သိမ်းပြီး ✓",en:"Preset '"+nm+"' saved ✓"}),"ok");
}

