function v2Tier(n){ return n<=35?"subtle":n<=65?"natural":n<=85?"strong":"maximum"; }
/* Prompt composer — the two studies distilled. No TASK GUARD of its own:
   $("btnGen") appends the canonical D.guards.core+textBan to every request.
   Composed in English (all engines are English-prompted). ≈700–1100 chars —
   under seedream's 2000 promptMax; rhTruncatePrompt guards the RH path. */
function v2BuildPrompt(){
  var v=state.v2, n=v.strength, tier=v2Tier(n);
  var TIER_LINE={
    subtle:"Barely-detectable pass: the result must still read as an un-retouched photo.",
    natural:"Clean studio-natural finish.",
    strong:"Polished beauty-editorial finish.",
    maximum:"Flawless porcelain magazine finish — still photographic, never CGI."
  };
  var out=[];
  out.push("One-shot professional wedding-portrait skin retouch of IMAGE 1 — "+tier+" strength ("+n+"%).\n"+TIER_LINE[tier]);
  if(v.mode==="rt"||v.mode==="both"){
    var tx="SKIN TEXTURE — re-render, never blur, on ALL visible skin (face, ears, neck, chest, shoulders, arms and hands alike — one consistent finish, the body matching the face with no boundary at the jawline): remove blemishes, acne marks and dust-like spots at "+v.blemish+"% aggressiveness"+(v.blemish<50?", keep signature moles and beauty marks":"")+". Re-render skin texture the way a high-end frequency-separation retouch would — smooth tonal transitions, but realistic pore-level micro-texture and a fine film-like grain must stay visible at 100% zoom. Never gaussian-blurred, waxy or plastic skin.";
    if(v.deshine>0) tx+="\nRemove oily shine and sweat specular dots at "+v.deshine+"% — merge hard micro-highlights into one soft continuous glow.";
    /* v4.47 — the old always-on "teeth slightly brighter" clause invited the
       model to OPEN the mouth to show them (real drift reported by the
       owner). Lips are cleaned in place; teeth moved to an explicit opt-in
       control that only acts on already-visible teeth. */
    tx+="\nClean and even the lip gloss on the lips exactly as they are photographed.";
    out.push(tx);
  }
  if(v.mode==="col"||v.mode==="both"){
    var cx="SKIN COLOR — skin regions only: even out blotchy, reddish and dull gray patches; remove any orange/yellow color cast completely.";
    if(v.tone==="off"){
      cx+="\nDo not change the overall complexion or brightness — even out only, and keep face and body skin ONE consistent tone with no color break at the jaw or neck.";
    } else {
      var sw=V2_TONES.filter(function(s){ return s.hex===v.tone; })[0];
      if(sw) cx+="\nShift the complexion gently toward "+sw.label.en+" (hex "+sw.hex+") at "+v.toneStrength+"%, evenly across ALL visible skin — face, neck, chest, shoulders, arms and hands as one consistent tone. Refine, never change the person's natural skin tone identity.";
    }
    out.push(cx);
  }
  var ex=[];
  if(v.balance<0) ex.push("TEXTURE BIAS: preserve "+Math.abs(v.balance)+"% more of the original pore detail — err on the side of visible real skin.");
  if(v.balance>0) ex.push("SMOOTHING BIAS: allow "+v.balance+"% deeper smoothing on the low-frequency tone, texture still re-imposed on top.");
  if(v.hair!=="off") ex.push("HAIR: tame flyaway and baby hairs "+(v.hair==="soft"?"lightly, keeping a natural hairline":"thoroughly, for a clean editorial hairline")+" at 35% — keep strand detail, never blur the hair mass.");
  if(v.outfit!=="off") ex.push("OUTFIT: give fabric and jewelry a subtle clarity-and-sheen polish at "+(v.outfit==="soft"?"35%":"60%")+" — no color or design change.");
  /* v4.47 — opt-in face detail passes, each written so it can never change
     the pose, the expression, or how open the mouth/eyes are */
  if(v.teeth!=="off") ex.push("TEETH: ONLY where teeth are already visible between the photographed lips, make them "+(v.teeth==="soft"?"slightly cleaner and one shade brighter":"clean and evenly white — still natural enamel, never paper-white")+". If the mouth is closed, skip this entirely. NEVER part the lips, never widen the smile, never reveal teeth that are not visible.");
  if(v.eyes!=="off") ex.push("EYES: brighten the eye whites "+(v.eyes==="soft"?"subtly":"clearly")+" and reduce red veins; keep the natural catchlights, iris color, eyelid position and gaze direction — no change to eye shape, size or openness.");
  if(v.eyebags!=="off") ex.push("UNDER-EYE: reduce dark circles and puffiness "+(v.eyebags==="soft"?"gently, keeping a natural soft shadow":"thoroughly, for a fresh well-rested look")+" — keep the lower-lid crease real, never flatten the eye socket.");
  /* v4.47 — BODY: the same studio pass, below the chin */
  if(v.body!=="off") ex.push("BODY SKIN: retouch ALL visible body skin — neck, ears, chest, shoulders, underarms, arms, hands, back and legs — with the same texture-preserving pass as the face: even the tone so body skin matches the face, remove blemishes, bruises, strap marks, insect bites and stray spots"+(v.body==="strong"?", smooth rough elbows, knees and knuckles, and soften prominent veins":"")+". Realistic pore-level texture must remain on every retouched area.");
  if(v.shape!=="off") ex.push("BODY SHAPE (explicitly requested): very gently refine the silhouette — waist and upper arms at most 5% slimmer, posture line tidied, double chin reduced subtly. Anatomy, joints and proportions must stay fully natural and believable; clothing and background follow the refined edge cleanly.");
  if(ex.length) out.push(ex.join("\n"));
  out.push("PRESERVE EXACTLY: face geometry and identity; the pose and body position precisely as photographed; the exact expression; the mouth precisely as photographed — same lip position, same degree of openness (a closed mouth stays closed, teeth visibility unchanged), never add or widen a smile; eye and brow shape; the makeup design (clean it, never redesign it); hairstyle and hair volume; accessories, clothing, background pixels, framing and crop. "+(v.shape==="off"?"No liquify, no reshaping, no added or removed objects.":"No reshaping beyond the single subtle silhouette refinement requested above; no added or removed objects."));
  return out.join("\n\n");
}

